}

@media (min-width: 840px) {
  .app-docs__grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

/* Keyboard shortcut list inside the map hint stays readable on small screens. */
@media (max-width: 599px) {
  .zh-result {
    grid-template-columns: 64px minmax(0, 1fr);
  }
  .zh-result__thumb {
    width: 64px;
    height: 64px;
  }
}

.app-map__skip {
  display: flex;
  flex-wrap: wrap;
  gap: var(--zh-size-mini);
