  padding: 0;
  list-style: none;
}

.app-map__hint {
  margin-top: var(--zh-size-mini);
}

/* ---- Detail panel (aside/dialog) ---- */
.app-detail {
  position: fixed;
  z-index: var(--zh-z-detail);
  inset: 0;
  background: var(--zh-white);
  overflow: auto;
  border-left: var(--zh-rule) solid var(--zh-black);
  box-shadow: var(--zh-shadow-card);
  animation: zh-slide-in var(--zh-transition-default) var(--zh-easing-decelerate);
}


/* Touch: vertical swipes scroll the page, horizontal swipes pan the map. A full
   height map with `touch-action: none` would trap the scroll on phones. */
@media (pointer: coarse) {
  .app-map {
    height: 56vh;
    touch-action: pan-y;
  }
}

@media (min-width: 840px) {
  .app-detail {
    inset: 0 0 0 auto;
    width: min(560px, 90vw);
