#!/usr/bin/env node
/**
 * Focused check for the compare/saved-maps module (public/app/compare.js).
 * Pin two real records, open the side-by-side comparison, check the previews,
 * shareable URL and keyboard closing behaviour.
 */
import { spawn } from 'node:child_process';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

const port = Number(process.argv[2] || 9560);
const BASE = 'http://127.0.0.1:8787';
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-cmp-'));
spawn('/usr/bin/chromium', ['--headless=new', `--remote-debugging-port=${port}`, '--no-sandbox', '--disable-gpu', '--hide-scrollbars', '--window-size=1440,960', `--user-data-dir=${userDataDir}`, 'about:blank'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function endpoint(p) { for (let i = 0; i < 60; i += 1) { try { const r = await fetch(`http://127.0.0.1:${port}${p}`); if (r.ok) return r.json(); } catch {} await sleep(250); } throw new Error('no cdp'); }
await endpoint('/json/version');
const target = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map(); const errors = [];
ws.onmessage = (m) => {
  const d = JSON.parse(m.data);
  if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); }
  else if (d.method === 'Runtime.exceptionThrown') errors.push('EXC ' + (d.params.exceptionDetails?.exception?.description || d.params.exceptionDetails?.text));
  else if (d.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(d.params.type)) errors.push(d.params.type + ': ' + d.params.args?.map((a) => a.value ?? a.description).join(' '));
};
const send = (method, params = {}) => new Promise((resolve) => { const mid = ++id; pending.set(mid, resolve); ws.send(JSON.stringify({ id: mid, method, params })); });
const evaluate = async (e) => {
  const r = await send('Runtime.evaluate', { expression: e, returnByValue: true, awaitPromise: true });
  if (r.result?.exceptionDetails) throw new Error(r.result.exceptionDetails.exception?.description || 'eval failed');
  return r.result?.result?.value;
};
const press = async (key, keyCode, code) => { await send('Input.dispatchKeyEvent', { type: 'keyDown', key, windowsVirtualKeyCode: keyCode, code }); await send('Input.dispatchKeyEvent', { type: 'keyUp', key, windowsVirtualKeyCode: keyCode, code }); };
const click = async (selector) => {
  const box = await evaluate(`(() => { const n = document.querySelector(${JSON.stringify(selector)}); if (!n) return null; n.scrollIntoView({block:'center',behavior:'instant'}); const r = n.getBoundingClientRect(); return { x: r.left + r.width/2, y: r.top + r.height/2 }; })()`);
  if (!box) throw new Error('no element ' + selector);
  const common = { x: Math.round(box.x), y: Math.round(box.y), button: 'left', clickCount: 1 };
  await send('Input.dispatchMouseEvent', { type: 'mouseMoved', ...common });
  await send('Input.dispatchMouseEvent', { type: 'mousePressed', ...common });
  await send('Input.dispatchMouseEvent', { type: 'mouseReleased', ...common });
  await sleep(120);
};
const waitFor = async (expr, label, timeout = 20000) => {
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline) { try { if (await evaluate(expr)) return true; } catch {} await sleep(250); }
  throw new Error('timeout waiting for ' + label);
};

await send('Page.enable'); await send('Runtime.enable');
await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 960, deviceScaleFactor: 1, mobile: false });
await send('Page.navigate', { url: `${BASE}/?from=1816&to=1850` });
await waitFor(`document.querySelectorAll('#result-list > *').length > 0`, 'results');
await sleep(800);

const out = {};
out.modules = await evaluate(`document.documentElement.dataset.moduleErrors`);
out.panelPresent = await evaluate(`!!document.querySelector('#compare-panel')`);
out.addDisabledInitially = await evaluate(`document.querySelector('#compare-add').disabled`);

// Pin the first two results by expanding them and using the detail selection.
out.pins = await evaluate(`(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const items = [...document.querySelectorAll('#result-list > li')].slice(0, 2);
  const ids = [];
  for (const item of items) {
    const button = item.querySelector('button, a');
    button.click();
    await sleep(700);
    const id = new URLSearchParams(location.search).get('sel');
    document.querySelector('#compare-add').click();
    await sleep(400);
    ids.push(id);
  }
  return { ids, cmp: new URLSearchParams(location.search).get('cmp'), count: document.querySelector('#compare-count').textContent, rows: document.querySelectorAll('#compare-list li').length };
})()`);

await click('#compare-list li button'); // "Vergleichen"
await waitFor(`document.querySelector('#compare-view')?.hidden === false`, 'compare view');
await sleep(2500);
out.view = await evaluate(`(() => {
  const panes = [...document.querySelectorAll('#compare-view-body .app-compare__pane')];
  return {
    title: document.querySelector('#compare-view-title').textContent.slice(0, 90),
    panes: panes.length,
    images: panes.map((p) => { const img = p.querySelector('img'); return img ? { src: img.currentSrc || img.src, w: img.naturalWidth, loaded: img.complete && img.naturalWidth > 0 } : null; }),
    links: [...document.querySelectorAll('#compare-view-body a.zh-button')].map((a) => a.href),
    focused: document.activeElement?.id,
  };
})()`);

// keyboard: Esc closes and returns focus
await press('Escape', 27, 'Escape');
await sleep(400);
out.afterEsc = await evaluate(`({ viewHidden: document.querySelector('#compare-view').hidden, scrimHidden: document.querySelector('#scrim').hidden, bodyClass: document.body.className })`);

// share the comparison link and reload it
