import { spawn } from 'node:child_process';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
const port = 9880 + Math.floor(Math.random() * 40);
const userDataDir = await mkdtemp(path.join(tmpdir(), 'cdp-pinch-'));
spawn('/usr/bin/chromium', ['--headless=new', `--remote-debugging-port=${port}`, '--no-sandbox', '--disable-gpu', '--hide-scrollbars', '--window-size=390,844', `--user-data-dir=${userDataDir}`, 'about:blank'], { stdio: 'ignore' });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function endpoint(p) { for (let i = 0; i < 60; i += 1) { try { const r = await fetch(`http://127.0.0.1:${port}${p}`); if (r.ok) return r.json(); } catch {} await sleep(250); } throw new Error('no cdp'); }
await endpoint('/json/version');
const target = await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: 'PUT' }).then((r) => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map(); const logs = [];
ws.onmessage = (m) => { const d = JSON.parse(m.data); if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); } else if (d.method === 'Runtime.consoleAPICalled') logs.push(d.params.type + ': ' + d.params.args?.map((a) => a.value ?? a.description).join(' ').slice(0, 120)); };
const send = (method, params = {}) => new Promise((resolve) => { const mid = ++id; pending.set(mid, resolve); ws.send(JSON.stringify({ id: mid, method, params })); });
const evaluate = async (e) => { const r = await send('Runtime.evaluate', { expression: e, returnByValue: true, awaitPromise: true }); if (r.result?.exceptionDetails) return 'EXC ' + (r.result.exceptionDetails.exception?.description || '').slice(0,200); return r.result?.result?.value; };
await send('Page.enable'); await send('Runtime.enable'); await send('Network.enable'); await send('Network.setCacheDisabled', { cacheDisabled: true });
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });

for (const emulateTouch of [false, true]) {
  if (emulateTouch) await send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 5 });
  await send('Page.navigate', { url: 'http://127.0.0.1:8787/?sel=e-rara:6507640' });
  await sleep(6000);
  const ready = await evaluate(`(() => ({ state: document.querySelector('#viewer-stage')?.dataset.state, box: (() => { const r = document.querySelector('#viewer-stage')?.getBoundingClientRect(); return r ? { cx: Math.round(r.left + r.width/2), cy: Math.round(r.top + r.height/2) } : null; })() }))()`);
  await evaluate(`(() => { window.__evts = []; const stage = document.querySelector('#viewer-stage'); for (const type of ['pointerdown','touchstart','pointermove','touchmove','pointerup','touchend']) stage?.addEventListener(type, (e) => window.__evts.push(type + (e.pointerId !== undefined ? ':' + e.pointerId : '') + ':' + (e.pointerType || '')), true); return true; })()`);
  const before = await evaluate(`document.querySelector('.app-viewer__image')?.src || ''`);
  const c = ready.box;
  const tp = (x, y, id) => ({ x: Math.round(x), y: Math.round(y), id, radiusX: 12, radiusY: 12, force: 1 });
  await send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [tp(c.cx - 40, c.cy, 1), tp(c.cx + 40, c.cy, 2)] });
  for (let s = 1; s <= 6; s += 1) { await send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [tp(c.cx - 40 - s * 16, c.cy, 1), tp(c.cx + 40 + s * 16, c.cy, 2)] }); await sleep(60); }
  await send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  await sleep(2500);
  const after = await evaluate(`({ src: (document.querySelector('.app-viewer__image')?.src || '').slice(-46), events: (window.__evts || []).slice(0, 14), touchAction: getComputedStyle(document.querySelector('#viewer-stage')).touchAction })`);
  console.log('touchEmulation=' + emulateTouch, JSON.stringify({ ready: ready.state, before: before.slice(-46), after }));
}
process.exit(0);
